import json

with open('/workspace/batch_composition_v2.json') as f:
    data = json.load(f)

# Count notes played per channel per pattern
counts = {} # (pattern, channel) -> count
for action in data:
    if action["name"] == "pattern_set_cell":
        args = action["arguments"]
        pat = args["pattern"]
        ch = args["channel"]
        if "note" in args:
            counts[(pat, ch)] = counts.get((pat, ch), 0) + 1

for pat in range(4):
    print(f"Pattern {pat}:")
    for ch in range(8):
        print(f"  Ch {ch}: {counts.get((pat, ch), 0)} notes")
